      "html_path": "works/gregory-nazianzus-oration-29/index.html#p-19",
      "label": "제3신학강론 (제29강론) 19",
      "location": "19",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:6d2df9344645a9eaaa9c07c53b1f64957c5d6028b8ccb47b640116a21fecbf27",
        "text": "Οὗτος γὰρ ὁ νῦν σοι καταφρονούμενος, ἦν ὅτε καὶ ὑπὲρ σὲ ἦν· ὁ νῦν ἄνθρωπος καὶ ἀσύνθετος ἦν. ὃ μὲν ἦν, διέμεινεν· ὃ δὲ οὐκ ἦν, προσέλαβεν. ἐν ἀρχῇ ἦν ἀναιτίως· τίς γὰρ αἰτία θεοῦ; ἀλλὰ καὶ ὕστερον γέγονε δι’ αἰτίαν (ἡ δὲ ἦν τὸ σὲ σωθῆναι τὸν ὑβριστήν, ὃς διὰ τοῦτο περιφρονεῖς θεότητα, ὅτι τὴν σὴν παχύτητα κατεδέξατο) διὰ μέσου νοὸς ὁμιλήσας σαρκί, καὶ γενόμενος ἄνθρωπος, ὁ κάτω θεός· ἐπειδὴ συνανεκράθη θεῷ, καὶ γέγονεν εἷς, τοῦ κρείττονος ἐκνικήσαντος, ἵνα γένωμαι τοσοῦτον θεός, ὅσον ἐκεῖνος ἄνθρωπος. ἐγεννήθη μέν, ἀλλὰ καὶ ἐγεγέννητο· ἐκ γυναικὸς μέν, ἀλλὰ καὶ παρθένου. τοῦτο ἀνθρώπινον, ἐκεῖνο θεῖον. ἀπάτωρ ἐντεῦθεν, ἀλλὰ καὶ ἀμήτωρ ἐκεῖθεν. ὅλον τοῦτο θεότητος. ἐκυοφορήθη μέν, ἀλλ’ ἐγνώσθη προφήτῃ καὶ αὐτῷ κυοφορουμένῳ, καὶ προσκιρτῶντι τοῦ λόγου, δι’ ὃν ἐγένετο. ἐσπαργανώθη μέν, ἀλλ’ ἀποσπαργανοῦται τὰ τῆς ταφῆς ἀνιστάμενος. ἐν φάτνῃ μὲν ἀνεκλίθη, ἀλλ’ ὑπ’ ἀγγέλων ἐδοξάσθη, καὶ ὑπ’ ἀστέρος ἐμηνύθη, καὶ ὑπὸ μάγων προσεκυνήθη. πῶς σὺ προσπταίεις τῷ βλεπομένῳ, μὴ σκοπῶν τὸ νοούμενον; ἐφυγαδεύθη μὲν εἰς Αἴγυπτον, ἀλλὰ φυγαδεύει τὰ Αἰγυπτίων. οὐκ εἶχεν εἶδος οὐδὲ κάλλος παρὰ Ἰουδαίοις, ἀλλὰ τῷ Δαβὶδ ὡραῖος ἦν κάλλει παρὰ τοὺς υἱοὺς τῶν ἀνθρώπων, ἀλλ’ ἐπὶ τοῦ ὄρους ἀστράπτει, καὶ ἡλίου φωτοειδέστερος γίνεται, τὸ μέλλον μυσταγωγῶν."
      },
      "title": "제3신학강론 (제29강론)",
      "translation": {
        "notes": [
          "말씀은 본래 그러하셨던 것을 유지하며 인간성을 취하신다. 정신을 매개로 육신과 결합하셨다는 문장은 인간의 정신도 성육신에 포함한다.",
          "‘아래의 인간은 하나님이 되었다’와 ‘그분이 인간이 되신 만큼 나도 하나님이 된다’는 성육신과 구원의 연합을 설명하는 표현이다. 앞에서는 신성을 버리지 않고 인간성을 취하셨다고 밝힌다.",
          "태중에서 뛰논 예언자는 누가복음 1:41의 세례 요한이다. 구유, 별과 동방박사, 이집트 피신, 산 위의 빛남은 탄생과 변화산 이야기의 장면들이다. 아름다움의 대조는 이사야 53:2와 시편 45:2를 잇는다."
        ],
        "revision_id": "sha256:6c6add3790fffebf092bd96fd604ebf49ad1047a3506751b570f34fa611661fc",
        "text": "지금 그대가 업신여기는 이분은, 한때 그대보다 높이 계셨다. 지금 인간이신 분은 결합되지 않은 분이기도 하셨다. 본래 그러하셨던 것은 그대로 유지하셨고, 본래 아니셨던 것을 취하셨다. 처음에 계셨던 것은 어떤 이유 때문도 아니었다. 하나님이신 데 무슨 이유가 있겠는가? 그러나 나중에 인간이 되신 데는 이유가 있었다. 그 이유는 모욕하는 그대를 구원하는 것이었다. 그대는 그분이 그대의 무거운 육신을 받아들이셨다는 이유로 신성을 멸시한다. 그분은 정신을 매개로 육신과 결합하셨고, 인간이 되셨다. 아래의 인간은 하나님이 되었다. 하나님과 결합하여 하나가 되었기 때문이다. 더 높은 쪽이 우세해졌으며, 그분이 인간이 되신 만큼 나도 하나님이 되게 하려는 것이다. 그분은 태어나셨으며, 이미 태어나신 분이셨다. 여인에게서 태어나셨으며, 그 여인은 처녀였다. 여인에게서 태어남은 인간의 일이고, 처녀에게서 태어남은 신적인 일이다. 이쪽에서는 아버지가 없으시며, 저쪽에서는 어머니가 없으시다. 이 모든 것이 신성에 속한다. 그분은 태중에 계셨으며, 자신도 태중에 있던 예언자가 그분을 알아보았다. 그 예언자는 자신을 존재하게 한 말씀을 향해 뛰놀았다. 그분은 포대기에 싸이셨으며, 부활하시면서 장례의 수의를 벗어 던지셨다. 구유에 누이셨으며, 천사들에게 영광을 받으셨다. 별이 그분을 알렸고, 동방박사들이 그분께 경배했다. 그대는 왜 생각으로 깨달아야 할 것을 살피지 않고, 보이는 것에 걸려 넘어지는가? 그분은 이집트로 쫓겨나셨으며, 이집트의 것들을 쫓아내신다. 유대인들 가운데서는 모양도 아름다움도 없으셨다. 그러나 다윗에게는 사람의 아들들보다 아름다우신 분이었다. 산 위에서는 번쩍이며 해보다 더 빛나신다. 장차 올 것을 신비 가운데 알려 주시는 것이다."
      },
      "work_id": "gregory-nazianzus-oration-29",
