      "html_path": "works/gregory-nazianzus-oration-30/index.html#p-5",
      "label": "제4신학강론 (제30강론) 5",
      "location": "5",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:fa4a59f7a1f8824afbd8f2ff8204fda4e7b256790fea70c116b79d5cd38562e5",
        "text": "τούτῳ σύναπτε καὶ τὴν ὑποταγήν, ἣν ὑποτάσσεις τῷ πατρὶ τὸν υἱόν. τί, λέγεις, ὡς νῦν οὐχ ὑποτεταγμένου; δεῖται δὲ ὅλως ὑποταγῆναι θεῷ θεὸς ὤν; ὡς περὶ λῃστοῦ τινός, ἢ ἀντιθέου, ποιῇ τὸν λόγον. ἀλλ’ οὕτω σκόπει· ὅτι ὥσπερ κατάρα ἤκουσε δι’ ἐμὲ ὁ τὴν ἐμὴν λύων κατάραν· καὶ ἁμαρτία ὁ αἴρων τὴν ἁμαρτίαν τοῦ κόσμου· καὶ Ἀδὰμ ἀντὶ τοῦ παλαιοῦ γίνεται νέος· οὕτω καὶ τὸ ἐμὸν ἀνυπότακτον ἑαυτοῦ ποιεῖται, ὡς κεφαλὴ τοῦ παντὸς σώματος. ἕως μὲν οὖν ἀνυπότακτος ἐγὼ καὶ στασιώδης, τῇ τε ἀρνήσει τοῦ θεοῦ καὶ τοῖς πάθεσιν, ἀνυπότακτος τὸ κατ’ ἐμὲ καὶ Χριστὸς λέγεται. ὅταν δὲ ὑποταγῇ αὐτῷ τὰ πάντα, - ὑποταγήσεται δὲ καὶ τῇ ἐπιγνώσει καὶ τῇ μεταποιήσει, - τότε καὶ αὐτὸς τὴν ὑποταγὴν πεπλήρωκε, προσάγων ἐμὲ τὸν σεσωσμένον. τοῦτο γὰρ ἡ ὑποταγὴ Χριστοῦ, κατά γε τὸν ἐμὸν λόγον, ἡ τοῦ πατρικοῦ θελήματος πλήρωσις. ὑποτάσσει δὲ καὶ υἱὸς πατρί, καὶ υἱῷ πατήρ· ὁ μὲν ἐνεργῶν, ὁ δὲ εὐδοκῶν, ὃ καὶ πρότερον εἴπομεν. καὶ οὕτω τὸ ὑποτεταγμένον ὁ ὑποτάξας θεῷ παρίστησιν, ἑαυτοῦ ποιούμενος τὸ ἡμέτερον. τοιοῦτον εἶναί μοι φαίνεται καὶ τό· Ὁ θεός, ὁ θεός μου, πρόσχες μοι, ἵνα τί ἐγκατέλιπές με; οὐ γὰρ αὐτὸς ἐγκαταλέλειπται, ἢ ὑπὸ τοῦ πατρός, ἢ ὑπὸ τῆς ἑαυτοῦ θεότητος, ὃ δοκεῖ τισίν, ὡς ἂν φοβουμένης τὸ πάθος, καὶ διὰ τοῦτο συστελλομένης ἀπὸ τοῦ πάσχοντος. τίς γὰρ ἢ γεννηθῆναι κάτω τὴν ἀρχήν, ἢ ἐπὶ τὸν σταυρὸν ἀνελθεῖν ἠνάγκασεν; ἐν ἑαυτῷ δέ, ὅπερ εἶπον, τυποῖ τὸ ἡμέτερον. ἡμεῖς γὰρ ἦμεν οἱ ἐγκαταλελειμμένοι καὶ παρεωραμένοι πρότερον, εἶτα νῦν προσειλημμένοι καὶ σεσωσμένοι τοῖς τοῦ ἀπαθοῦς πάθεσιν· ὥσπερ καὶ τὴν ἀφροσύνην ἡμῶν καὶ τὸ πλημμελὲς οἰκειούμενος τὰ ἑξῆς διὰ τοῦ ψαλμοῦ φησίν· ἐπειδὴ προδήλως εἰς Χριστὸν ὁ εἰκοστὸς πρῶτος ψαλμὸς ἀναφέρεται."
      },
      "title": "제4신학강론 (제30강론)",
      "translation": {
        "notes": [
          "아들의 복종은 고린도전서 15:28과 연결된다. 그리스도가 몸의 머리로서 인간의 불순종을 자신의 것으로 삼고, 구원받은 인간을 아버지께 데려가신다고 설명한다.",
          "저주가 되심은 갈라디아서 3:13, 죄가 되심은 고린도후서 5:21, 세상의 죄를 없애심은 요한복음 1:29의 표현이다. 하나님의 뜻이 이루어지는 일과 아버지와 아들의 활동 관계를 함께 말한다.",
          "버림받음의 외침은 그리스어 시편 21편, 현대 한국어 성경의 시편 22:1 및 마태복음 27:46과 연결된다. 강론에 실린 ‘나를 돌아보소서’도 포함하여 옮겼다."
        ],
        "revision_id": "sha256:a440fa628050b1b5b2c0b357c9850cfece99697ba301ee639bbd21bdeae339b8",
        "text": "그대가 아들을 아버지께 복종시키는 그 복종도 이 설명에 연결하라. 무엇인가? 지금은 복종하지 않으셨다는 뜻인가? 하나님이신 분이 하나님께 복종하실 필요가 과연 있는가? 그대는 어떤 강도나 하나님을 대적하는 자를 논하듯 말한다. 그러나 이렇게 살펴보라. 나의 저주를 푸시는 분이 나 때문에 저주라고 불리셨고, 세상의 죄를 없애시는 분이 죄라고 불리셨으며, 옛 아담 대신 새 아담이 되셨듯, 그분은 온 몸의 머리로서 나의 불순종도 자신의 것으로 삼으신다. 그러므로 내가 하나님을 부인하고 정념들에 매여 불순종하며 분쟁을 일으키는 동안, 그리스도도 나와의 관계에서 불순종하신다고 불린다. 그러나 만물이 그분께 복종하면, 하나님을 알아보고 변화됨으로 복종하게 될 것이다. 그때 그분 자신도 구원받은 나를 데리고 오셔서 복종을 완성하신다. 내 설명에 따르면, 그리스도의 복종은 아버지 뜻을 이루는 일이기 때문이다. 아들도 만물을 아버지께 복종시키시고, 아버지도 아들에게 복종시키신다. 아들은 활동하시고 아버지는 기뻐하신다. 앞서 말한 것과 같다. 이렇게 복종을 이루신 분은 복종한 이를 하나님께 바치시며, 우리의 것을 자신의 것으로 삼으신다. 다음 말도 나에게는 같은 뜻으로 보인다. “하나님, 나의 하나님, 나를 돌아보소서. 왜 나를 버리셨습니까?” 그분 자신이 아버지에게 버림받거나 자신의 신성에게 버림받은 것이 아니다. 어떤 이들은 그렇게 생각한다. 마치 신성이 고난을 두려워해서, 고난받는 분에게서 물러난 것처럼 생각한다. 그러나 누가 애초에 아래에서 태어나시도록, 또는 십자가에 오르시도록 강제로 시켰는가? 앞서 말했듯, 그분은 자신의 안에 우리의 처지를 나타내신다. 전에 버려지고 외면당했던 이들은 우리였다. 이제는 고난에 흔들리지 않는 분의 고난으로 받아들여지고 구원받았다. 마찬가지로 우리의 어리석음과 잘못을 자신의 것으로 삼아, 시편의 이어지는 말들을 하신다. 시편 21편은 분명히 그리스도에게 적용되기 때문이다."
      },
