      "html_path": "works/gregory-nazianzus-oration-30/index.html#p-14",
      "label": "제4신학강론 (제30강론) 14",
      "location": "14",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:ec8c0e42fbd2b4256120d696539aef892559e4ded50ee50792c19721812893a7",
        "text": "Ἐννατον ἐκεῖνο φήσουσι τό· Πάντοτε ζῶν εἰς τὸ ἐντυγχάνειν ὑπὲρ ἡμῶν. εὖ γε καὶ λίαν μυστικῶς τε καὶ φιλανθρώπως. τὸ γὰρ ἐντυγχάνειν οὐχ, ὡς ἡ τῶν πολλῶν συνήθεια, τὸ ζητεῖν ἐκδίκησιν ἔχει· τοῦτο γάρ πὼς καὶ ταπεινότητος· ἀλλὰ τὸ πρεσβεύειν ὑπὲρ ἡμῶν τῷ λόγῳ τῆς μεσιτείας· ὡς καὶ τὸ πνεῦμα ὑπὲρ ἡμῶν ἐντυγχάνειν λέγεται. Εἷς γὰρ θεός, εἷς καὶ μεσίτης θεοῦ καὶ ἀνθρώπων, ἄνθρωπος Ἰησοῦς χριστός. πρεσβεύει γὰρ ἔτι καὶ νῦν, ὡς ἄνθρωπος, ὑπὲρ τῆς ἐμῆς σωτηρίας, ὅτι μετὰ τοῦ σώματός ἐστιν, οὗ προσέλαβεν, ἕως ἂν ἐμὲ ποιήσῃ θεὸν τῇ δυνάμει τῆς ἐνανθρωπήσεως, κἂν μηκέτι κατὰ σάρκα γινώσκηται, τὰ σαρκικὰ λέγω πάθη καί, χωρὶς τῆς ἁμαρτίας, ἡμέτερα. οὕτω δὲ καὶ παράκλητον ἔχομεν Ἰησοῦν οὐχ ὡς ὑπὲρ ἡμῶν προκαλινδούμενον τοῦ πατρός, καὶ προσπίπτοντα δουλικῶς. ἄπαγε τὴν δούλην ὄντως ὑπόνοιαν, καὶ ἀναξίαν τοῦ πνεύματος. οὔτε γὰρ τοῦ πατρὸς τοῦτο ἐπιζητεῖν, οὔτε τοῦ υἱοῦ πάσχειν, ἢ ὡς περὶ θεοῦ διανοεῖσθαι δίκαιον· ἀλλ’ οἷς πέπονθεν, ὡς ἄνθρωπος, πείθει καρτερεῖν, ὡς λόγος καὶ παραινέτης. τοῦτο νοεῖταί μοι ἡ παράκλησις."
      },
      "title": "제4신학강론 (제30강론)",
      "translation": {
        "notes": [
          "영원한 간구는 히브리서 7:25, 성령의 간구는 로마서 8:26, 한 중보자는 디모데전서 2:5, 예수라는 대언자는 요한일서 2:1과 연결된다.",
          "παράκλητος와 παράκλησις는 대언자와 대언으로 옮겼다. 마지막에는 인간으로서 겪으신 고난을 근거로 우리에게 인내를 권하는 뜻을 제시한다(Mason 131쪽)."
        ],
        "revision_id": "sha256:baaac45d94e5f38015a5a0a3209db37fefb4bb244ff2666b6c6bc45ca0107e4a",
        "text": "아홉째로 그들은 다음 말을 내세울 것이다. “우리를 위해 간구하려고 언제나 살아 계신다.” 좋은 말이며, 매우 신비롭고 인간을 사랑하는 말이다. 간구한다는 말은 많은 이들이 흔히 쓰는 뜻처럼, 보복을 요구한다는 뜻이 아니다. 그것은 어느 정도 낮은 처지에 속한다. 중보라는 관계에 따라 우리를 위해 대표가 되어 말씀하신다는 뜻이다. 성령도 우리를 위해 간구하신다고 한다. “하나님은 한 분이시며, 하나님과 인간 사이의 중보자도 한 분, 인간 예수 그리스도이시다.” 그분은 지금도 인간으로서 나의 구원을 위해 대표가 되어 말씀하신다. 자신이 취하신 몸과 함께 계시기 때문이다. 인간이 되심의 능력으로 나를 하나님이 되게 하실 때까지 그러하신다. 이제 육신을 따라 알려지지 않으시더라도 그러하다. 여기서 육신이라는 말은 죄를 제외한 우리의 육체적 고난을 뜻한다. 이처럼 우리에게는 예수라는 대언자가 계신다. 우리를 위해 아버지 앞에서 엎드려 뒹굴며 종처럼 간청하신다는 뜻이 아니다. 참으로 종에게 어울리며 성령께 어울리지 않는 그 생각을 치우라. 아버지께서 이를 요구하시거나 아들이 이를 겪으신다고 생각하는 일은, 하나님에 관한 합당한 생각이 아니기 때문이다. 그분은 인간으로서 겪으신 고난으로, 말씀과 권고자로서 우리에게 인내하도록 권하신다. 나는 대언을 이렇게 이해한다."
      },
      "work_id": "gregory-nazianzus-oration-30",
      "work_passage_id": "gregory-nazianzus-oration-30:14"
