      "html_path": "works/athanasius-serapion-4/index.html#p-15",
      "label": "세라피온에게 보낸 제4서신 15",
      "location": "15",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:c4a98b4e07590b40082bc6d8f5d0eb3d3e6beb3d707463480377feaf61bb9ba4",
        "text": "Αἱρετικοὶ μὲν οὖν κατὰ τὴν ἰδίαν ἀπαιδευσίαν ἐμάνησαν· καὶ οἱ μὲν τὰ σωματικὰ βλέποντες τοῦ Σωτῆρος ἠρνήσαντο τὸ, « Ἐν ἀρχῇ ἦν ὁ Λόγος· » οἱ δὲ τὰ τῆς θεότητος θεωροῦντες ἠγνόησαν τὸ, « Ὁ Λόγος σὰρξ ἐγένετο. » Ὁ δὲ πιστὸς καὶ ἀποστολικὸς ἀνὴρ, εἰδὼς τὴν τοῦ Κυρίου φιλανθρωπίαν, βλέπων μὲν τὰ τῆς θεότητος σημεῖα, θαυμάζει τὸν ἐν τῷ σώματι Κύριον· θεωρῶν δὲ πάλιν καὶ τὰ τοῦ σώματος ἴδια, ὑπερεκπλήσσεταί, κατανοῶν τὴν ἐν αὐτοῖς τῆς θεότητος ἐνέργειαν. Τοιαύτης δὲ οὖσης τῆς ἐκκλησιαστικῆς πίστεως, ὅταν τινὲς εἰς τὰ ἀνθρώπινα βλέποντες, ἴδωσι τὸν Κύριον διψῶντα, ἢ κοπιῶντα, ἢ πάσχοντα, καὶ μόνον φλυαρήσωσιν ὡς κατὰ ἀνθρώπου τοῦ Σωτῆρος, ἀμαρτάνουσι μὲν μεγάλως, δύνανται δὲ ὅμως, ταχέως μεταγιγνώσκοντες, λαμβάνειν συγγνώμην, ἔχοντες πρόφασιν τὴν τοῦ σώματος ἀσθένειαν (ἔχουσι γὰρ καὶ τὸν Ἀπόστολον συγγνώμην αὐτοῖς νέμοντα, καὶ οἷον χεῖρα αὐτοῖς ἐν τῷ λέγειν ἐκτείνοντα, ὅτι: « Καὶ ὁμολογουμένως μέγα ἐστὶ τῆς εὐσεβείας μυστήριον, Θεὸς ἐφανερώθη ἐν σαρκί »). Ὅταν δὲ πάλιν τὰ τῆς θεότητος ἔργα θεωροῦντες τινες, διστάζωσι περὶ τῆς τοῦ σώματος φύσεως, καὶ αὐτοὶ μὲν ἀμαρτάνουσι τὰ μέγιστα, ὅτι, καίτοι βλέποντες ἐσθιόντα καὶ πάσχοντα, φαντάζονται φαντασίαν· συγγνώσκειν δὲ ὅμως καὶ τούτοις ταχέως μεταγιγνώσκουσιν ὁ Χριστὸς δύναται, διὰ τὸ καὶ αὐτοὺς ἔχειν πρόφασιν τὴν ἐκ τῶν ἔργων ὑπὲρ ἄνθρωπον μεγαλειότητα. Ἐπειδὰν δὲ τὴν ἀμφοτέραν τούτων ἄγνοιαν καὶ πήρωσιν ὑπερβάντες οἱ δοκοῦντες ἔχειν τοῦ νόμου τὴν γνῶσιν (οἷοι ἦσαν οἱ τότε Φαρισαῖοι) εἰς μανίαν τραπέντες, καὶ αὐτὸν τὸν ἐν τῷ σώματι ὄντα Λόγον τέλεον ἀρνήσωνται, ἢ καὶ τὰ τῆς θεότητος ἔργα τῷ διαβόλῳ καὶ τοῖς τούτου δαιμονίοις ἀναφέρωσιν· εἰκότως ἀσύγγνωστον ἔχουσι τὴν ἐκ τῆς τοιαύτης ἀσεβείας ἐπιτιμίαν. Τόν τε γὰρ διάβολον εἰς Θεὸν ἐλογίζοντο, καὶ τὸν ἀληθινὸν καὶ ὄντως ὄντα Θεὸν, οὐδὲν πλέον ἐν τοῖς ἔργοις ἔχειν τῶν δαιμόνων ἡγήσαντο."
      },
      "title": "세라피온에게 보낸 제4서신",
      "translation": {
        "notes": [
          "주님의 인간적 모습을 보고 신성을 부인하는 경우와 신적 일을 보고 몸의 실재를 부인하는 경우를 나눈다. 두 경우 모두 빨리 생각을 바꾸면 용서받을 수 있다고 설명한다.",
          "이어 신적 일을 악마에게 돌리는 경우를 다룬다. 딤전 3:16 인용은 Migne판의 ‘하나님이 육체 안에 나타나셨다’라는 형태를 따른다."
        ],
        "revision_id": "sha256:92342c8fccb076e146063ca9cd1b35487b1e17bda8a895c24df051c6075411eb",
        "text": "그러므로 이단자들은 자기들의 무지 때문에 미쳐 버렸습니다. 어떤 이들은 구주의 몸에 관한 일들을 보고, “태초에 말씀이 계셨다”라는 말씀을 부인했습니다. 어떤 이들은 신성의 일들을 보고, “말씀이 육체가 되셨다”라는 말씀을 알지 못했습니다. 그러나 믿음이 있고 사도의 가르침을 따르는 사람은, 주님이 사람을 사랑하심을 알기에, 신성의 표적들을 보며, 몸 안에 계신 주님께 경탄합니다. 또 몸에 고유한 일들을 보면서, 더욱 놀랍니다. 그 안에서 신성이 일하시는 것을 알기 때문입니다. 교회의 신앙은 이와 같습니다. 어떤 사람들이 인간의 일들을 보며, 주님이 목마르시고 지치시거나 고난받으시는 것을 보고, 구주를 그저 사람으로 여겨 그분을 거슬러 헛말을 한다면, 크게 죄를 짓는 것입니다. 그래도 빨리 생각을 바꾸면 용서받을 수 있습니다. 몸의 연약함을 구실로 삼을 수 있기 때문입니다. 사도도 그들에게 용서를 베풀며, 말씀으로 그들에게 손을 내밀듯 하기 때문입니다. “참으로 경건의 신비는 크다. 하나님이 육체 안에 나타나셨다.” 또 어떤 사람들이 신성의 일들을 보며, 그분 몸의 본성에 관해 의심한다면, 그들 역시 매우 큰 죄를 짓는 것입니다. 그분이 먹고 고난받으시는 것을 보면서도, 그것을 환영이라고 상상하기 때문입니다. 그러나 그들도 빨리 생각을 바꾸면 그리스도께서 용서하실 수 있습니다. 그분의 일들에 드러난, 사람을 초월하는 위대함을 그들 역시 구실로 삼을 수 있기 때문입니다. 그러나 이 두 경우의 무지와 눈멂을 넘어, 율법을 안다고 여기는 사람들이, 당시 바리새인들이 그런 사람들이었습니다. 미친 생각에 빠져, 몸 안에 계신 말씀 자신을 완전히 부인하거나, 신성의 일들을 악마와 그 마귀들에게 돌린다면, 그런 불경함으로 받는 벌에는 당연히 용서가 없습니다. 그들은 악마를 하나님으로 여겼고, 참으로 계신 진실한 하나님은, 그분의 일에서 마귀들보다 나은 것이 전혀 없다고 생각했기 때문입니다."
      },
      "work_id": "athanasius-serapion-4",
      "work_passage_id": "athanasius-serapion-4:15"
